const event = $json;
const payload = event.payload;

if (
  !event.event_id ||
  !event.lease_token ||
  !event.customer_email ||
  !payload?.resolution
) {
  throw new Error("Incomplete claimed recovery event");
}

const customerName =
  typeof payload.customer_name === "string" &&
  payload.customer_name.trim()
    ? payload.customer_name.trim()
    : "Customer";

const subject = "Update on your support case";

const message = [
  `Hello ${customerName},`,
  "",
  "We have an update regarding your recent support case.",
  "",
  payload.resolution,
  "",
  `Reference: ${event.refund_transaction_id}`,
  "",
  "If you need assistance, please contact our support team.",
  "",
  "Best regards,",
  "Support Team",
].join("\n");

return {
  json: {
    event_id: event.event_id,
    lease_token: event.lease_token,
    recipient: event.customer_email,
    subject,
    message,
  },
};

const item = $json;

// Replace with an inbox you own and control.
const TEST_INBOX = "zebihaider123@gmail.com";

if (!TEST_INBOX || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(TEST_INBOX)) {
  throw new Error("Configure your authorized test inbox before sending");
}

if (!item.event_id || !item.lease_token || !item.message) {
  throw new Error("Missing recovery task ownership or message");
}

return {
  json: {
    ...item,
    recipient: TEST_INBOX,
    original_recipient: item.recipient,
  },
};

